# Generated by build.py from recipe.yml for recipe stomp-join-a-topic-across-two-protocols. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--topic', '"orders/#;retain"', '--idle-timeout', '1', 'stomp://127.0.0.1:8080/', 'mqtt://127.0.0.1:8081/', 'mqtt5://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh join.sh 8080 8082 /topic/orders/created orders/created } finally { Stop-Process $server0 }
